          reply(wrapError(error))
        }
      }
    } else {
      startReplyChannel.setMessageHandler(nil)
    }
    /// Stops the reply [requestId]. Nothing more is sent for it.
    let cancelReplyChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.stream_chat_flutter_ai_ondevice.OnDeviceModelHostApi.cancelReply\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      cancelReplyChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let requestIdArg = args[0] as! String
        do {
          try api.cancelReply(requestId: requestIdArg)
          reply(wrapResult(nil))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      cancelReplyChannel.setMessageHandler(nil)
    }
    /// Starts downloading the model. Progress arrives on
    /// [OnDeviceModelEventApi.downloadEvents].
    let startDownloadChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.stream_chat_flutter_ai_ondevice.OnDeviceModelHostApi.startDownload\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      startDownloadChannel.setMessageHandler { _, reply in
        do {
          try api.startDownload()
